from build import *

S = '5-ai'


def halaman():
    isi = ''
    isi += section('biaya', 'Sebelum mulai', 'Tiga layanan internet yang dipakai', table(
        ['Layanan', 'Untuk apa', 'Biaya', 'Wajib?'],
        [['Bot Telegram', 'perintah dan foto dari HP', 'gratis', 'ya'],
         ['Gemini API (Google AI Studio)', 'otak AI: ngobrol, memutuskan gerakan, melihat foto', 'gratis dengan batas harian', 'tidak, tanpa ini robot tetap bisa dikendalikan lewat perintah'],
         ['Groq', 'mengubah suaramu jadi teks, dan AI cadangan kalau jatah Gemini habis', 'gratis dengan batas harian', 'tidak, tapi disarankan'],
         ['Google TTS (lewat library audio)', 'robot berbicara', 'gratis, tapi bukan layanan resmi', 'tidak; kalau berhenti bekerja, robot tetap menjawab lewat Telegram']]) + '''
<div class="panel">
  <h3>Batas gratis Gemini</h3>
  <p>Gemini dipakai lewat <b>Google AI Studio</b> tanpa kartu kredit. Batasnya dihitung per proyek dan per model (permintaan per menit dan per hari), dan Google tidak lagi mengumumkannya di dokumentasi: angka yang berlaku untukmu hanya terlihat di <a href="https://aistudio.google.com/rate-limit">halaman batas AI Studio</a> dan bisa berubah sewaktu-waktu. Jatah harian kembali penuh tengah malam waktu Pasifik, sekitar pukul 15.00-16.00 WITA.</p>
  <p>Contoh jatah gratis yang terlihat di satu akun pada November 2026: <b>Gemini 3.5 Flash Lite</b> 15 per menit dan 500 per hari, <b>Gemma 4 31B</b> 30 per menit dan 14.400 per hari, sedangkan Gemini 2.5 Flash Lite hanya 20 per hari. Kode memakai Gemini 3.5 Flash Lite sebagai otak utama dan Gemma 4 31B (kunci yang sama) sebagai cadangan pertama.</p>
  <p>Satu obrolan robot = satu permintaan; pertanyaan yang membuat robot memotret biasanya dua (memutuskan melihat, lalu menjelaskan fotonya). Kalau jatah Gemini habis, robot otomatis pindah ke Gemma, lalu ke <b>Groq</b> kalau kunci Groq diisi (Tahap 3). Di tingkat gratis, Google boleh memakai isi pertanyaan dan foto untuk memperbaiki layanannya; jangan kirim hal yang pribadi.</p>
</div>''')

    t = ''
    t += stage(S, 1, 'Buat bot Telegram', ['HP dengan Telegram', 'ESP32-S3', 'Library UniversalTelegramBot dan ArduinoJson'], [
        'Di Telegram, cari <b>@BotFather</b>, kirim <code>/newbot</code>, beri nama (misalnya Zond Robot) dan username yang diakhiri "bot". Simpan <b>token</b> yang diberikan.',
        'Cari <b>@userinfobot</b>, tekan Start, simpan angka <b>Id</b>-mu. Robot hanya akan menurut ke ID ini.',
        'Buka bot barumu dan tekan <b>Start</b>.',
        'Sudah membuat bot untuk stasiun cuaca? Buat bot baru untuk robot, supaya keduanya tidak berebut pesan.',
        'Install library <b>UniversalTelegramBot</b> (Brian Lough) dan <b>ArduinoJson</b> (Benoit Blanchon).',
        'Isi WiFi, token, dan chat ID di kode tes, upload ke S3, lalu kirim pesan ke bot.',
    ], code=kode_tes('tes_telegram'),
        ok_='Bot mengirim "Halo dari ESP32-S3!" dan membalas setiap pesanmu.',
        gagal=['"GAGAL kirim": token salah ketik (harus lengkap dengan angka dan titik dua), chat ID salah, atau belum menekan Start di bot.', 'WiFi tidak tersambung: ESP32 hanya bisa 2.4 GHz.'])

    t += stage(S, 2, 'API key Gemini (gratis)', ['Akun Google'], [
        'Buka <a href="https://aistudio.google.com">aistudio.google.com</a> dan masuk dengan akun Google.',
        '<b>Get API key → Create API key</b>, pilih atau buat proyek baru. Salin kuncinya (diawali <code>AIza</code>). Tidak perlu kartu kredit.',
        'Buka <a href="https://aistudio.google.com/rate-limit">halaman batas</a> dan lihat jatah per hari tiap model. Kode memakai <code>gemini-3.5-flash-lite</code> (cepat, bisa melihat foto) dengan cadangan <code>gemma-4-31b-it</code>. Kalau jatahmu berbeda, tulis nama model yang jatah per harinya paling besar di <code>MODEL</code> (kode tes) dan <code>GEMINI_MODEL</code> (kode otak).',
        'Isi kunci di kode tes, upload ke S3, ketik pertanyaan di Serial Monitor.',
    ], code=kode_tes('tes_gemini'),
        ok_='Jawaban AI muncul dalam beberapa detik. Kode 400 dengan API_KEY_INVALID = kunci salah, 403 = kunci tidak diizinkan, 404 = nama model salah atau sudah tidak tersedia, 429 = jatah habis atau terlalu sering.',
        learn='Kode ini mengirim pertanyaan dalam format JSON ke alamat <code>generativelanguage.googleapis.com</code> lewat HTTPS, dengan kunci di header <code>x-goog-api-key</code>. Koneksinya terenkripsi, tapi demi kesederhanaan sertifikat server tidak diperiksa (<code>setInsecure</code>). Untuk proyek rumahan ini cukup; jangan pakai pola ini untuk data sensitif.')

    t += stage(S, 3, 'Groq: suara ke teks dan AI cadangan (opsional)', ['Akun Groq'], [
        'Buka <a href="https://console.groq.com">console.groq.com</a>, daftar, lalu <b>API Keys → Create API Key</b>. Salin kuncinya (diawali <code>gsk_</code>).',
        'Kode otak memotong suaramu per kalimat (WAV 16 kHz, paling lama 6 detik), mengirimnya ke model <code>whisper-large-v3-turbo</code> dengan bahasa Indonesia, dan menerima teksnya. Secara bawaan robot hanya merekam setelah kamu menekan BICARA (di layar atau panel web), supaya jatah Groq tidak habis.',
        'Kunci yang sama juga jadi cadangan otak AI: kalau Gemini menolak (misalnya jatah harian habis), kode otak bertanya ke model <code>GROQ_MODEL</code> di Groq, yang juga bisa melihat foto.',
        'Rekamanmu dikirim ke server Groq. Baca kebijakan privasi mereka kalau itu penting bagimu. Tidak mengisi kunci ini juga tidak apa-apa: tombol BICARA tidak berfungsi dan tidak ada cadangan AI.',
        'Opsional dan <b>berbayar</b>: Claude Haiku dari Anthropic. Buat kunci di <a href="https://console.anthropic.com">console.anthropic.com</a> (perlu mengisi saldo), lalu isi <code>ANTHROPIC_API_KEY</code> di kode otak. Biaya dihitung per pemakaian, foto ikut dihitung. Haiku hanya dipakai kalau kamu memilihnya di panel web (bagian Otak AI) atau dengan <code>/ai haiku</code> di Telegram. Kalau saldonya habis, robot kembali ke AI gratis.',
    ], ok_='Kamu punya kunci gsk_ yang siap diisi di kode otak.')

    t += stage(S, 4, 'Pasang library audio dan upload kode otak', ['Semua rangkaian Bagian 3', 'Badan dan kamera menyala'], [
        'Library <b>ESP32-audioI2S</b> tidak ada di Library Manager. Buka <a href="https://github.com/schreibfaul1/ESP32-audioI2S/releases">halaman rilisnya</a>, unduh ZIP versi <b>4.0.0</b> (Source code zip). Di Arduino IDE: <b>Sketch → Include Library → Add .ZIP Library</b>, pilih file ZIP itu.',
        'Pastikan LovyanGFX, UniversalTelegramBot, dan ArduinoJson sudah terpasang.',
        'Buka <a href="../kode/robot_otak/robot_otak.ino" download>robot_otak.ino</a>. Isi bagian KONFIGURASI: WiFi, token, chat ID, API key Gemini, API key Groq (boleh kosong, tapi disarankan sebagai cadangan), dan <code>KAMERA_ALAMAT</code> dengan IP kamera dari Bagian 4.',
        'Ganti <code>NAMA_ROBOT</code> (bawaan <code>Zond</code>) dan <code>NAMA_PEMILIK</code> sesukamu. Pilih nama robot yang pendek dan jarang muncul di obrolan sehari-hari, karena dalam mode dengar terus robot hanya menanggapi perintah suara yang menyebut namanya.',
        'Jam, hari, dan tanggal di layar diambil dari internet setelah WiFi tersambung. Sesuaikan <code>ZONA_WAKTU</code>: <code>WIB-7</code> untuk Jawa dan Sumatra, <code>WITA-8</code> untuk Bali, NTB, dan Sulawesi, <code>WIT-9</code> untuk Maluku dan Papua. Suhu hanya tampil kalau badan punya sensor suhu.',
        'Cuaca diambil gratis dari Open-Meteo, tanpa kunci. Isi <code>CUACA_KOTA</code>, <code>CUACA_LAT</code>, dan <code>CUACA_LON</code> dengan lokasimu: di Google Maps klik kanan titik rumahmu, angka pertama lintang (LAT), angka kedua bujur (LON). Bawaannya Mataram.',
        'Pastikan badan memakai <a href="../kode/robot_badan/robot_badan.ino" download>robot_badan.ino</a> terbaru (ada perintah <code>T</code> untuk belok presisi pakai giroskop). Kalau kode badanmu lebih lama, upload ulang sekali lewat USB dan isi lagi <code>BATERAI_FAKTOR</code>-mu. Setiap saklar dinyalakan, biarkan robot diam sekitar 1 detik: badan mengukur giroskop saat diam.',
        'Atur Tools seperti Bagian 3 Tahap 1 (<b>PSRAM: OPI PSRAM</b>, <b>Partition Scheme: 16M Flash (3MB APP/9.9MB FATFS)</b>). Upload pertama wajib lewat kabel USB. Kompilasi pertama bisa beberapa menit.',
        'Setelah menyala pertama kali, layar meminta kalibrasi sentuh: sentuh ujung panah di tiap sudut. Hasilnya disimpan. Untuk kalibrasi ulang, sentuh layar saat S3 baru dinyalakan.',
        'Upload berikutnya bisa lewat WiFi, tanpa membongkar robot: laptop dan robot di WiFi yang sama, buka <b>Tools → Port</b>, pilih port jaringan <code>zond at 10.x.x.x</code>, lalu Upload seperti biasa. Layar menampilkan kemajuannya; jangan matikan robot. Isi <code>OTA_SANDI</code> kalau tidak ingin orang lain di WiFi yang sama bisa mengganti kodenya (Arduino IDE akan menanyakannya saat upload).',
    ], code=kode_teks(open(KODE + 'robot_otak/robot_otak.ino', encoding='utf-8').read().split('// ======================= PIN')[0], 'robot_otak.ino (bagian atas: pengaturan dan konfigurasi)')
        + '<p class="cap">Kode lengkap sekitar 6.000 baris (panel web di dalamnya sudah dipadatkan): <a href="../kode/robot_otak/robot_otak.ino" download>unduh robot_otak.ino</a>. Jangan unggah file yang sudah berisi token dan API key ke tempat publik.</p>',
        ok_='Layar menampilkan wajah dengan dua mata yang berkedip, baris status di atas berisi baterai dan jarak dari badan, speaker berkata "Halo, aku Zond. Aku siap.", dan bot mengirim "Zond menyala".',
        gagal=['Error kompilasi "Audio.h: No such file": library audio belum terpasang dari ZIP.', 'Error "Sketch too big" atau upload WiFi ditolak: Partition Scheme belum 3MB APP. Ganti, lalu upload sekali lewat USB.',
               'Port jaringan tidak muncul di Tools → Port: tunggu sekitar 1 menit setelah robot menyala, tutup dan buka lagi Arduino IDE, atau upload lewat USB. Upload WiFi yang gagal di tengah tidak merusak apa pun: kode lama tetap jalan.', 'Restart terus dengan pesan PSRAM: menu PSRAM belum OPI PSRAM.',
               '"badan belum terhubung" di layar: cek kabel UART dan GND (Bagian 3 Tahap 6).', 'Tidak bersuara tapi tes speaker berhasil: Google TTS mungkin sedang menolak. Jawaban tetap dikirim lewat Telegram.'])

    fitur = table(['Coba ini', 'Yang terjadi'], [
        ['Buka alamat panel di HP atau laptop (satu WiFi dengan robot). Alamatnya dikirim bot saat robot menyala, atau ketik <code>/panel</code>', 'panel kontrol: tahan tombol arah untuk jalan, lepas untuk berhenti; kamera langsung, arah kepala, lagu, radio, volume, kotak teks untuk menyuruh robot bicara, dan pilihan otak AI. Di laptop, tombol panah atau W A S D juga bisa'],
        ['Panel web atau Telegram: <code>/belok 90</code>, <code>/belok -90</code>, <code>/balik</code>', 'robot berputar di tempat tepat 90° ke kanan, 90° ke kiri, atau 180°, diukur giroskop MPU6050. AI juga memakainya kalau kamu bilang "putar balik"'],
        ['Telegram: <code>/cuaca</code>', 'suhu, peluang hujan, dan keadaan cuaca hari ini dari Open-Meteo. Versi singkatnya tampil di layar di samping tanggal, dan ditambahkan ke pengingat sebelum jam 11 siang'],
        ['Telegram: <code>/alarm 06:30 berangkat kerja</code>, <code>/alarm harian 04:30 sholat subuh</code>, <code>/alarm</code>, <code>/alarm hapus 2</code>', 'pengingat sekali atau setiap hari (paling banyak 12): robot mengucapkan pesannya dan mengirimnya ke Telegram. Di panel web (bagian Alarm dan pengingat) kamu juga bisa memilih hari tertentu dan bunyi tambahan: radio atau lagu dari SD. Jadwal sholat diisi sendiri satu per satu. Bisa juga lewat AI: "ingatkan aku jam 7 berangkat kerja"'],
        ['Panel web: <b>Jelajah sendiri</b> (pilih 5-30 menit), atau Telegram <code>/jelajah 10</code>', 'robot maju sampai ada halangan sekitar 40 cm di depan, lalu belok 70-130° ke arah acak (pakai giroskop). Kalau buntu atau tersangkut, ia mundur lalu berbalik. Berhenti sendiri kalau waktunya habis, baterai tinggal 10%, robot miring, atau tombol STOP ditekan. Tombol arah, <code>/biasa</code>, atau STOP menghentikannya. Bisa juga lewat AI: "jalan-jalan dong"'],
        ['Panel web: bagian <b>Baterai</b>, atau Telegram <code>/baterai</code>', 'isi baterai dalam persen, grafik tegangan 6 jam terakhir (satu titik per menit), dan perkiraan sisa waktu dari setengah jam terakhir. Peringatan suara dan Telegram saat tinggal 20% dan 10%. Persennya juga tampil di layar'],
        ['Biarkan saja', 'ekspresi berubah sendiri: mengantuk antara jam 22.00 dan 05.00 kalau 2 menit tidak dipakai, lemas kalau baterai lemah, kaget kalau diangkat, pusing kalau diputar-putar dengan tangan'],
        ['Panel web: centang <b>Fitur kamera AI</b>, lalu <b>Lihat sekeliling</b> (atau <code>/sekeliling</code>)', 'kepala menoleh ke kiri, depan, dan kanan, memotret tiap arah, lalu AI menceritakan sekelilingnya lewat Telegram. Bawaannya mati karena tiap kali memakai AI dengan 3 foto (jatah AI lebih cepat habis)'],
        ['Panel web: <b>Main suit</b> (atau <code>/suit</code>), setelah Fitur kamera AI dicentang', 'robot berkata "Suit! Batu, gunting, kertas!" lalu memotret tepat setelah "kertas". Tunjukkan tanganmu 30-50 cm di depan kamera sebelum kalimatnya selesai. AI menebak tanganmu, robot mengumumkan pemenang dan skornya'],
        ['Telegram: <code>/ai</code>, <code>/ai gemma</code>, <code>/ai haiku</code>, <code>/ai otomatis</code>', 'melihat atau mengganti otak AI. Pilihan tersimpan walau robot dimatikan. Otomatis = Gemini, lalu Gemma, lalu Groq (semua gratis)'],
        ['Layar: <b>Beranda</b>', 'wajah Zond, jam, baterai, dan dua tombol besar: BICARA dan MENU. Wajah hanya tampil di Beranda. Malam hari setelah 2 menit tidak dipakai, wajah diganti jam besar. Halaman lain kembali sendiri ke Beranda setelah 45 detik tidak disentuh'],
        ['Layar: <b>MENU</b>', 'enam ubin: Musik (lagu SD, radio, podcast, murottal), Info (status robot, cuaca, jadwal sholat, berita, kalender, kurs, Wikipedia), Alat (mode gerak, kamera, alarm, timer, kalkulator, senter, penerjemah, catatan, rekam suara, galeri foto), Main (suit, tic-tac-toe, 2048, ketuk terbang), Pesan, dan Setelan. Tombol dijalankan saat jari diangkat; tombol ◀ di kiri atas untuk kembali. Daftar yang panjang (114 surah, ratusan lagu) punya tombol &lt;&lt; dan &gt;&gt; untuk melompat 5 halaman'],
        ['Layar: Musik → <b>Lagu SD</b>', 'judul, garis waktu, sebelumnya / putar-jeda / berikutnya, acak, ulang, volume, dan daftar lagu. Lagu berikutnya diputar sendiri setelah satu lagu selesai'],
        ['Layar: Musik → <b>Podcast</b>', 'daftar podcast dari <code>DAFTAR_PODCAST</code> di kode (bawaannya SBS Indonesian, episode baru tiap hari). Ketuk podcastnya untuk melihat 15 episode terbaru, ketuk episode untuk memutarnya; ada JEDA, STOP, dan volume. Untuk menambah podcast, cari halamannya di podnews.net lalu salin alamat RSS-nya ke <code>DAFTAR_PODCAST</code>. Podcast yang khusus Spotify atau Noice tidak punya RSS terbuka, jadi tidak bisa diputar'],
        ['Layar: Musik → <b>Murottal</b>, atau Telegram <code>/murottal 36</code>', '114 surah. Ketuk surah untuk memutarnya; setelah selesai, surah berikutnya diputar sendiri. Tombol Qari memilih pembaca (Alafasy, Abdul Basit, Al-Ghamdi, As-Sudais, Al-Husary, Al-Muaiqly, Ad-Dosari) dari mp3quran.net. Supaya bisa tanpa internet, simpan file di SD card folder <code>/murottal</code> dengan nama tiga angka: <code>001.mp3</code> sampai <code>114.mp3</code>; file di SD selalu diputar lebih dulu'],
        ['Layar: Info → <b>Status robot</b>', 'baterai dengan grafiknya, jarak depan dan belakang, kemiringan, suhu. Tab JARINGAN menampilkan QR code alamat panel web: pindai dari HP untuk membukanya'],
        ['Layar: Info → <b>Cuaca</b>', 'suhu sekarang, 12 jam ke depan (suhu dan batang peluang hujan), dan 3 hari ke depan, dari Open-Meteo untuk lokasi <code>CUACA_LAT</code>/<code>CUACA_LON</code>'],
        ['Layar: Info → <b>Jadwal sholat</b>, atau Telegram <code>/sholat</code>', 'waktu sholat hari ini dengan hitung mundur ke waktu berikutnya dan tanggal Hijriah, dihitung api.aladhan.com memakai metode Kementerian Agama RI untuk lokasi yang sama dengan cuaca. Tombol Pengingat: mati, suara ("Sudah masuk waktu Dzuhur"), atau suara + adzan dari SD (<code>/adzan.mp3</code>, Subuh memakai <code>/adzan_subuh.mp3</code> kalau ada). AI juga tahu jadwal ini, jadi bisa ditanya "jam berapa maghrib?"'],
        ['Layar: Info → <b>Berita</b>', 'judul berita terbaru dari RSS Antara, CNN Indonesia, atau Antara Teknologi (pilih di tab atas). Ketuk judul untuk membaca ringkasannya, tombol BACAKAN untuk mendengarnya. Daftar sumber ada di <code>SUMBER_BERITA</code> di kode'],
        ['Layar: Info → <b>Kalender</b>', 'kalender bulanan, hari ini disorot biru. Tanggal merah dan cuti bersama 2026-2027 sesuai SKB 3 Menteri (daftar di <code>DAFTAR_LIBUR</code>; tambahkan tahun berikutnya setelah SKB-nya terbit)'],
        ['Layar: Info → <b>Kurs</b>, atau Telegram <code>/kurs</code>', 'kurs rupiah untuk USD, EUR, SGD, MYR, SAR, JPY (per 100), CNY, AUD dari ExchangeRate-API (gratis, diperbarui sekali sehari, kurs tengah, bukan kurs jual-beli bank)'],
        ['Layar: Info → <b>Wikipedia</b>, atau Telegram <code>/wiki Gunung Rinjani</code>', 'ketuk CARI DENGAN SUARA lalu sebutkan topiknya; ringkasan artikel tampil di layar dan bisa dibacakan. Hasil pencarian AI ("siapa Sultan Hasanuddin?") juga muncul di sini'],
        ['Layar: Alat → <b>Mode gerak</b>', 'Biasa, Jaga, Ikuti, Jelajah. Ikuti dan Jelajah mulai setelah hitung mundur 5 detik. Selama robot bergerak sendiri, layar merah: sentuh di mana saja untuk berhenti'],
        ['Layar: Alat → <b>Alarm</b>', 'daftar alarm (ketuk satu, lalu HAPUS dua kali untuk menghapus) dan + TAMBAH: atur jam dan menit dengan + dan - (tahan untuk cepat), pilih Ulang (sekali, setiap hari, Senin-Jumat, Sabtu-Minggu) dan Bunyi (suara, radio, lagu SD). Saat alarm berbunyi, layar menampilkan TUNDA 5 MENIT dan MATIKAN; kalau tidak disentuh, pengingatnya diulang tiap 15 detik (paling banyak 5 kali) dan layar kembali ke Beranda setelah 3 menit'],
        ['Layar: Alat → <b>Timer</b>', 'tiga tab. Timer: 1-99 menit, tahan -1/+1 untuk mengubah cepat, layar alarm muncul saat waktunya habis. Pomodoro: 25 menit fokus, 5 menit istirahat, tiap kali ke-4 istirahat 15 menit; Zond mengumumkan tiap pergantian. Stopwatch: dengan tombol PUTARAN. Ketiganya tetap berjalan walau halamannya ditutup'],
        ['Layar: Alat → <b>Kalkulator</b>', 'tambah, kurang, kali, bagi, dan persen; kali dan bagi dihitung lebih dulu (2+3x4 = 14). Hasil sementara tampil di atas. Angka ditulis cara Indonesia: 1.234,5'],
        ['Layar: Alat → <b>Senter</b>, atau Telegram <code>/senter on</code> / <code>/senter off</code>', 'menyalakan LED flash di ESP32-CAM (kepala robot). Mati sendiri setelah 5 menit supaya LED tidak panas. Tombol LAYAR PUTIH membuat seluruh layar putih sebagai lampu cadangan'],
        ['Layar: Alat → <b>Penerjemah</b>, atau Telegram <code>/terjemah jepang selamat pagi</code>', 'ketuk BICARA, ucapkan kalimat bahasa Indonesia; AI menerjemahkannya dan Zond mengucapkannya dengan logat bahasa tujuan. Pilihan bahasa: Inggris, Arab, Jepang, Mandarin, Korea, Jawa, Sasak. Layar menampilkan cara bacanya dalam huruf latin karena font layar tidak punya huruf Arab, Jepang, atau Mandarin; Telegram menampilkan keduanya. Bahasa Sasak kurang dikuasai AI dan diucapkan dengan logat Indonesia, jadi hasilnya bisa kurang tepat'],
        ['Layar: Alat → <b>Catatan</b>, panel web (bagian Catatan), atau Telegram <code>/catat beli susu</code>', 'daftar tugas sampai 20 baris, tersimpan walau robot dimatikan. Di layar: + DENGAN SUARA lalu ucapkan catatannya, ketuk baris untuk menandai selesai (hijau), BERSIHKAN menghapus yang sudah selesai. Telegram: <code>/catat</code> (daftar), <code>/catat selesai 2</code>, <code>/catat hapus 2</code>, <code>/catat hapus selesai</code>'],
        ['Layar: Alat → <b>Rekam suara</b>', 'REKAM lalu bicara, SELESAI untuk berhenti (paling lama 1 menit). Rekaman disimpan sebagai WAV di SD card, folder <code>/rekaman</code>, dengan nama dari tanggal dan jam. Ketuk rekaman untuk memutarnya, HAPUS dua kali untuk menghapus. Satu menit sekitar 1,9 MB'],
        ['Layar: Alat → <b>Galeri foto</b>', 'FOTO memotret lewat kamera robot (640x480) dan menyimpannya di SD card, folder <code>/foto</code>. Tombol &lt; dan &gt; untuk berpindah foto (terbaru dulu), KIRIM untuk mengirimnya ke Telegram, HAPUS dua kali untuk menghapus. Foto bisa juga diambil dari kartunya di laptop'],
        ['Layar: Main → <b>Tic-tac-toe</b>', 'kamu X, Zond O, dan yang mulai bergantian. Level Mudah: separuh langkah Zond asal. Level Sulit: Zond menghitung semua kemungkinan, jadi paling bagus kamu bisa seri. Skor dihitung sampai level diganti'],
        ['Layar: Main → <b>2048</b>', 'usap papan ke kiri, kanan, atas, atau bawah (atau pakai tombol panah); dua petak berangka sama bergabung. Skor terbaik tersimpan walau robot dimatikan'],
        ['Layar: Main → <b>Ketuk terbang</b>', 'ketuk layar supaya burung naik, lewati celah di antara pipa. Skor terbaik tersimpan'],
        ['Layar: Setelan → <b>WiFi</b>', 'daftar WiFi di sekitar robot. Ketuk salah satu, ketik sandinya dengan keyboard layar, lalu SAMBUNG. WiFi ini tersimpan dan dicoba lebih dulu saat robot menyala; kalau gagal, robot memakai <code>WIFI_NAMA</code> dari kode. PAKAI WIFI KODE menghapus pilihan itu. Kalau robot menyala tanpa WiFi, ia mulai ulang sendiri setelah tersambung supaya panel web dan Telegram ikut jalan'],
        ['Keyboard layar (tombol KETIK di Catatan, Penerjemah, Wikipedia, dan sandi WiFi)', 'huruf kecil; ^ untuk satu huruf besar, 123 dan #+= untuk angka dan simbol, tahan &lt;- untuk menghapus cepat. Tombolnya kecil: tekan tepat di tengah huruf'],
        ['Layar: <b>STOP</b> (kanan atas, ada di semua halaman)', 'motor dan suara langsung berhenti saat ditekan, mode kembali biasa'],
        ['Layar: ketuk wajah di Beranda', 'tampilan kamera langsung (sentuh untuk menutup). Kalau ada pesan baru, ketuk wajah membuka pesannya'],
        ['Telegram: <code>/pesan Makan malam sudah siap</code>, atau kolom pesan di panel web', 'pesan tampil di layar (ikon amplop kuning di bilah atas), Zond mengucapkan "Ada pesan dari ...". Buka di MENU → Pesan: baca, bacakan, hapus. 10 pesan terakhir tersimpan walau robot dimatikan'],
        ['Layar: <b>Setelan</b>', 'suara bicara, otak AI, fitur kamera AI, kecerahan, redup malam, putar layar 180 derajat, kalibrasi sentuh, info WiFi, mulai ulang'],
        ['Ketuk BICARA (di layar atau tombol besar di panel web), lalu bicara, misalnya "maju sedikit"', 'robot merekam satu kalimat sampai kamu diam (paling lama 6 detik), menjawab, bergerak, dan mengirim percakapan ke Telegram. Cara bawaan, paling hemat'],
        ['Dengar terus: nyalakan di panel web atau <code>/dengar on</code>, lalu ucapkan "Zond, maju sedikit"', 'robot mendengar terus dan menanggapi kalimat yang menyebut namanya. Boros: setiap suara di ruangan dikirim ke Groq. <code>/dengar off</code> untuk kembali'],
        ['Telegram: <code>/status</code>', 'jarak, baterai, suhu, kelembapan, kemiringan'],
        ['Telegram: <code>/maju 800</code>, <code>/kiri</code>, <code>/stop</code>', 'gerak langsung tanpa AI'],
        ['Telegram: <code>/kepala 45 90</code>', 'kepala menoleh'],
        ['Telegram: <code>/foto</code>', 'foto dari kamera'],
        ['Telegram: <code>/lihat ada apa di depanmu?</code>', 'foto dikirim, AI menjelaskan isinya'],
        ['Telegram: pesan biasa, misalnya "maju sedikit lalu lihat ke kiri"', 'AI menjawab dan menggerakkan badan'],
        ['Tanya apa saja (suara atau Telegram), misalnya "jelaskan kenapa langit biru" atau "siapa Sultan Hasanuddin?"', 'obrolan dijawab singkat, pertanyaan yang butuh penjelasan dijawab sampai sekitar 6 kalimat. Kalau tidak yakin soal fakta, AI mencari dulu di Wikipedia (gratis) lalu menjawab dari ringkasannya. Zond mengingat 10 tanya-jawab terakhir sampai dimatikan. Berita hari ini tetap tidak ia ketahui: pencarian Google untuk Gemini hanya ada di paket berbayar'],
        ['Telegram: <code>/lagu</code>, <code>/putar hujan</code> (cukup sebagian nama), <code>/volume 15</code>, <code>/diam</code>', 'musik dari SD card: mp3, flac, wav, m4a, aac, ogg, opus'],
        ['Telegram: <code>/radio</code> + alamat stream', 'memutar radio internet (alamat stream MP3/AAC dari situs radio)'],
        ['Telegram: <code>/bilang selamat pagi</code>', 'robot mengucapkan teks'],
        ['Telegram: <code>/ikuti</code>', 'robot menjaga jarak 35-70 cm ke benda di depannya, misalnya kakimu'],
        ['Telegram: <code>/jaga</code>', 'robot diam; kalau jarak di depannya berubah jauh, ia berkata "Siapa itu?" dan mengirim foto'],
        ['Telegram: <code>/biasa</code>', 'keluar dari mode ikuti/jaga'],
    ])
    t += stage(S, 5, 'Coba semua kemampuan', ['Robot lengkap di meja, roda terangkat'], [
        'Mulai dari <code>/bantuan</code> di Telegram: bot mengirim daftar perintah.',
        'Coba satu per satu fitur di tabel di bawah. Roda tetap terangkat sampai Bagian 6.',
        'Ngobrol bebas lewat Telegram. AI tahu data sensor terbaru, jadi coba tanya "berapa suhu di sini?" atau "baterainya masih cukup?".',
    ], after=fitur,
        ok_='Semua perintah langsung (diawali /) berjalan. Obrolan AI menjawab dalam beberapa detik.',
        learn='AI diminta menjawab dalam format JSON: kalimat untuk diucapkan, ditambah daftar aksi seperti {"m":[150,150,800]} untuk maju. Kode otak menjalankan aksi itu satu per satu, dan badan tetap menolak gerakan yang berbahaya. Mode ikuti dan jaga hanya memakai sensor ultrasonik, jadi robot tidak bisa membedakan orang dan benda; ia mengikuti atau menjaga apa pun yang ada di depannya.',
        gagal=['AI menjawab tapi robot tidak bergerak: lihat Serial Monitor. Kalau ada "E DITOLAK", ada halangan atau tombol STOP terkunci.', 'Foto gagal: kamera menyala? IP di KAMERA_ALAMAT benar? Tab /stream di browser sudah ditutup?',
               'Jadwal sholat beda 1-3 menit dari jadwal masjid setempat: isi <code>SHOLAT_KOREKSI</code> dengan menit tambahan untuk Imsak, Subuh, Terbit, Dzuhur, Ashar, Maghrib, Terbenam, Isya, Tengah malam, dipisah koma. Contoh <code>"2,2,-2,2,2,2,0,2,0"</code> menambah 2 menit ke waktu sholat dan mengurangi 2 menit dari waktu terbit.',
               'Berita, kurs, atau jadwal sholat menulis "gagal diambil (kode -1)": WiFi lemah atau situsnya sedang sibuk. Keluar lalu buka lagi halamannya beberapa menit kemudian.',
               'Tombol layar sering meleset: buka Setelan → Kalibrasi sentuh. Tekan di tengah tombol dan tahan sebentar; layar resistif butuh tekanan, bukan sentuhan ringan.',
               'Mau kecerahan layar bisa diatur (dan redup sendiri di malam hari)? Cabut kabel LED layar dari rel 3,3 V, sambungkan ke <b>IO38</b>, lalu isi <code>#define LAYAR_LED 38</code>. Cek dulu ada transistor kecil (tiga kaki, tulisan Q1) di dekat pin LED modulmu; hampir semua modul merah 2,8" punya. Tanpa transistor, lampu layar menarik arus terlalu besar untuk pin S3.',
               'Senter menulis "Kamera tidak menjawab": ESP32-CAM belum menyala, atau alamatnya belum ditemukan (isi IP kamera di <code>KAMERA_ALAMAT</code>). LED flash sengaja diredupkan di kode mata (<code>analogWrite</code> 60) supaya tidak panas; naikkan angkanya di <code>robot_mata.ino</code> kalau kurang terang, paling tinggi 255, dan jangan menyalakannya lama di nilai itu.',
               'Rekaman terdengar pelan atau berdesis: mikrofon INMP441 menangkap paling jelas dari jarak 30-50 cm, dengan lubang kecilnya menghadap ke mulut. Desis halus adalah bising mikrofon, normal untuk modul ini.',
               'Galeri menulis "Foto tidak bisa dibaca": file di <code>/foto</code> bukan JPEG dari kamera robot, atau ukurannya lebih dari 600 KB. Foto yang diambil Zond sendiri selalu bisa dibaca.',
               'Podcast menulis "gagal diambil" atau episodenya tidak bunyi: alamat RSS-nya pindah atau episodenya bukan MP3/AAC. Coba buka alamat RSS itu di browser; lihat juga baris <code>[audio]</code> di Serial Monitor.',
               'Murottal tidak bunyi padahal WiFi tersambung: alamat qari di mp3quran.net mungkin berubah. Cocokkan isi <code>DAFTAR_QARI</code> dengan kolom <code>server</code> di https://mp3quran.net/api/v3/reciters, atau pakai file di SD.',
               'Ketuk terbang terasa patah-patah: layar 2,8" ini paling cepat sekitar 20 gambar per detik lewat kabel SPI. Naikkan <code>LAYAR_MHZ</code> ke 40 kalau kabelnya pendek; kalau layar jadi bergaris, kembalikan ke 27.',
               'WiFi rumah tidak muncul di daftar: ESP32 hanya bisa WiFi 2,4 GHz, dan WiFi tersembunyi tidak tampil. Aktifkan 2,4 GHz di router atau isi namanya di <code>WIFI_NAMA</code>.',
               'BICARA menghasilkan "Tidak terdengar jelas": bicara lebih dekat ke mikrofon, atau GROQ_API_KEY belum diisi.',
               'Robot tidak menanggapi saat namanya disebut: lihat Serial Monitor. Baris "[dengar] tanpa nama, diabaikan" menunjukkan apa yang didengar; kalau namanya ditulis jauh berbeda, ganti NAMA_ROBOT dengan nama yang lebih jelas diucapkan. Robot juga tidak mendengar selama speaker berbunyi, termasuk saat musik atau radio diputar.',
               '<code>/belok</code> menjawab "Badan belum punya giroskop": kode badan masih versi lama, robot berbelok memakai waktu (kurang tepat). Upload ulang robot_badan.ino. Menjawab "Roda selip atau macet": lantai licin, karpet tebal, atau baterai lemah.',
               'Suit sering "tanganmu tidak terlihat jelas": ruangan kurang terang, atau tangan terlalu jauh atau terlambat ditunjukkan. Lihat foto kamera di panel web untuk memastikan tanganmu masuk gambar.',
               'Jelajah terus menabrak kaki kursi atau meja: sensor ultrasonik tidak melihat benda tipis. Setelah 5 detik jarak depan tidak berubah, robot menganggap dirinya tersangkut lalu mundur dan berbalik. Untuk ruangan penuh kaki kursi, jelajahi ruangan lain.',
               'Persen baterai naik-turun beberapa angka saat motor jalan: tegangan turun sesaat saat motor menarik arus. Angkanya dihaluskan, tapi perkiraan sisa waktu baru akurat setelah 10-30 menit.',
               'Robot berkata "Jatah AI gratis sedang habis": batas harian Gemini (dan Groq kalau diisi) sudah terpakai. Tunggu jatahnya kembali sekitar pukul 15.00-16.00 WITA, atau pilih model lain dengan jatah lebih besar di halaman batas AI Studio.'])

    t += stage(S, 6, 'Suara cowok', ['Kode otak terbaru', 'Laptop satu WiFi dengan robot'], [
        'Suara bawaan Google Translate adalah suara cewek. Kode otak memakai suara <b>Microsoft Edge</b> (fitur Baca dengan suara keras) untuk suara cowok berlogat Indonesia: <code>id-ID-ArdiNeural</code>. Gratis, tanpa kunci, dan tanpa jatah harian.',
        'Di kode otak, <code>SUARA_EDGE</code> berisi nama suaranya. Pilihan bahasa Indonesia: <code>id-ID-ArdiNeural</code> (cowok) dan <code>id-ID-GadisNeural</code> (cewek). <code>SUARA_EDGE_CEPAT</code> mengatur kecepatan (misalnya <code>+10%</code>) dan <code>SUARA_EDGE_NADA</code> tinggi suara (misalnya <code>-5Hz</code> supaya lebih berat).',
        'Penerjemah memakai suara asli tiap bahasa: Guy (Inggris), Hamed (Arab), Keita (Jepang), Yunxi (Mandarin), InJoon (Korea), dan Dimas (Jawa).',
        'Upload kode otak (lewat WiFi seperti Tahap 4), lalu ketik <code>/bilang halo, aku Zond</code> di Telegram.',
        'Ganti suara di Setelan → Suara bicara (urutannya Edge, Gemini, Google), di panel web (bagian Musik dan suara), atau di Telegram: <code>/suara edge</code>, <code>/suara gemini</code>, <code>/suara google</code>. Gemini TTS (<code>SUARA_GEMINI</code>, memakai <code>GEMINI_API_KEY</code>) tetap ada, tetapi jatah gratis hariannya kecil.',
    ], ok_='Robot bicara dengan suara cowok. Serial Monitor menulis baris seperti <code>[suara] Edge 900 ms (id-ID-ArdiNeural), kalimat ke-12 hari ini</code>.',
        learn='Robot membuka sambungan WebSocket aman ke server suara Edge, mengirim kalimatnya, dan menerima MP3 yang langsung ditulis ke memori flash S3 (partisi FATFS yang sama dengan syarat upload lewat WiFi), lalu memutarnya. Server meminta token yang berubah tiap 5 menit; kode menghitungnya sendiri dari jam robot (cara yang sama dengan library edge-tts). Ini layanan tidak resmi: Microsoft membuatnya untuk browser Edge, dan bisa mengubah syaratnya kapan saja. Karena itu, kalau Edge gagal, kalimat itu langsung diucapkan suara Google, jadi robot tidak pernah diam.',
        gagal=['Bot mengirim "Suara Edge gagal (kode 403)" terus-menerus: Microsoft mengubah token atau versi yang diterima. Robot memakai suara Google sambil menunggu. Cek library edge-tts di GitHub (rany2/edge-tts): kalau ada versi baru, salin isi <code>CHROMIUM_FULL_VERSION</code> dari <code>constants.py</code> ke <code>EDGE_VERSI</code> di kode otak, lalu upload ulang.',
               'Kode -107 (jam belum tersinkron): robot belum mendapat jam dari internet. Biasanya hilang sendiri beberapa detik setelah WiFi tersambung.',
               'Kode -108 (tidak ada audio): nama di <code>SUARA_EDGE</code> salah ketik. Huruf besar-kecilnya harus persis, misalnya <code>id-ID-ArdiNeural</code>.',
               'Pesan galat berisi <code>TLS: SSL - Memory allocation failed</code>: RAM internal ESP32-S3 tidak cukup untuk sambungan aman. Kode otak memindahkan buffer sambungan aman ke PSRAM saat menyala, jadi pastikan <b>Tools → PSRAM: OPI PSRAM</b> dan Serial Monitor menulis <code>PSRAM: 8388608 byte</code>. Kalau masih muncul, upload ulang kode otak terbaru.',
               'Kode -1, -2, atau -109: sambungan ke server putus atau lambat. Robot mencoba sekali lagi, lalu memakai suara Google 2 menit sebelum mencoba Edge lagi.',
               'Serial Monitor menulis <code>penyimpanan flash TIDAK ADA</code>: Partition Scheme masih Huge APP. Ganti ke 16M Flash (3MB APP/9.9MB FATFS) lalu upload lewat USB.'])

    isi += section('rakit', 'Langkah', 'Pasang kecerdasan', '<div class="parts" style="gap:16px">' + t + '</div>')
    isi += section('aman', 'Penting', 'Keamanan dan privasi', ul([
        'Token bot, API key Gemini, dan API key Groq sama dengan password. Jangan unggah ke GitHub atau kirim ke orang lain. Kalau bocor, hapus kuncinya di AI Studio atau console Groq dan buat yang baru.',
        'Robot hanya menurut ke chat ID-mu. Orang lain yang menemukan bot-mu akan dibalas "aku hanya menurut ke pemilikku".',
        'Kamera dan mikrofon bisa merekam orang lain di rumah. Kalau dengar terus dinyalakan, setiap kalimat yang terdengar dikirim ke Groq untuk dicek apakah menyebut nama robot (paling banyak 10 kalimat per menit). Beritahu orang di rumah, dan matikan robot kalau tidak dipakai. Secara bawaan dengar terus mati: robot hanya mendengar setelah tombol BICARA.',
        'Mode jaga bukan alarm keamanan sungguhan: sensor ultrasonik bisa terkecoh tirai yang bergerak, dan bisa melewatkan orang di samping.',
    ]))
    lead = 'Bagian ini menyalakan kecerdasan robot: Telegram untuk perintah dari HP, Gemini untuk berpikir dan melihat, Groq untuk mendengar dan sebagai AI cadangan. Setiap layanan dites sendiri sebelum kode otak lengkap di-upload.'
    return S, 'Kecerdasan', lead, isi, 'Menyalakan kecerdasan robot: bot Telegram, Gemini API gratis untuk ngobrol dan melihat foto, suara ke teks, mode ikuti dan jaga.'
